import{_ as t,o as a,a as r,a2 as i}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"shipping-method-development/getting-started.md","filePath":"shipping-method-development/getting-started.md","lastUpdated":1789464754000}'),o={name:"shipping-method-development/getting-started.md"};function s(d,e,n,c,h,p){return a(),r("div",null,e[0]||(e[0]=[i('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>A shipping method in Bagisto is a carrier: a class that quotes a rate for the cart, added from a package through merged configuration. This section builds one carrier, then explains each of its parts, without editing a core package.</p><h2 id="what-you-ll-build" tabindex="-1">What You&#39;ll Build <a class="header-anchor" href="#what-you-ll-build" aria-label="Permalink to &quot;What You&#39;ll Build&quot;">​</a></h2><p><strong><code>Webkul\\CustomExpressShipping</code></strong>, a package that adds the carrier <code>custom_express_shipping</code>:</p><ul><li>an <strong>Express Delivery (1-2 Days)</strong> option on the checkout&#39;s shipping step</li><li>a rate charged once per order, or once per item that ships</li><li>a <strong>Custom Express Shipping</strong> section in the admin&#39;s shipping method configuration, with its status, title, description, rate and pricing type per channel</li></ul><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>Paths are relative to <code>packages/Webkul/CustomExpressShipping/src</code>.</p><table tabindex="0"><thead><tr><th>Part</th><th>File</th><th>Plugs into</th></tr></thead><tbody><tr><td>Carrier configuration</td><td><code>Config/carriers.php</code></td><td>Merged into <code>config(&#39;carriers&#39;)</code>; its <code>class</code> key names the carrier class</td></tr><tr><td>Carrier class</td><td><code>Carriers/CustomExpressShipping.php</code></td><td>Extends <code>Webkul\\Shipping\\Carriers\\AbstractShipping</code>; <code>calculate()</code> returns the rate</td></tr><tr><td>System configuration</td><td><code>Config/system.php</code></td><td>Merged into <code>config(&#39;core&#39;)</code> as the section <code>sales.carriers.custom_express_shipping</code>, which the carrier&#39;s <code>getConfigData()</code> reads</td></tr><tr><td>Service provider</td><td><code>Providers/CustomExpressShippingServiceProvider.php</code></td><td>Merges both files; listed in <code>bootstrap/providers.php</code></td></tr></tbody></table><p>At checkout, <code>Webkul\\Shipping\\Shipping::collectRates()</code> creates every carrier in <code>config(&#39;carriers&#39;)</code>, calls its <code>calculate()</code> and groups the rates for the shipping step. The checkout does this only for a cart with stockable items, and saves the customer&#39;s choice only if a collected rate carries the same <code>method</code> code.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Bagisto 2.5, installed and running: see <a href="./../getting-started/installation.html">Installation</a>.</li><li>How a package is autoloaded and its provider registered: see <a href="./../package-development/getting-started.html">Package Development</a>.</li></ul><h2 id="the-path" tabindex="-1">The Path <a class="header-anchor" href="#the-path" aria-label="Permalink to &quot;The Path&quot;">​</a></h2><ol><li><a href="./create-your-first-shipping-method.html">Creating Your First Shipping Method</a>: build the package by hand and see its rate at checkout. To scaffold it instead, see <a href="./../tools/package-generator.html#payment-and-shipping-method-packages">Package Generator</a>.</li><li><a href="./understanding-carrier-configuration.html">Understanding Carrier Configuration</a>: the <code>carriers.php</code> keys, the admin section in <code>system.php</code>, and carriers with several services.</li><li><a href="./understanding-carrier-class.html">Understanding the Carrier Class</a>: what <code>AbstractShipping</code> provides, when <code>calculate()</code> runs, and common pricing patterns.</li></ol><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>Start by building the package.</p><p><strong>Continue to:</strong> <a href="./create-your-first-shipping-method.html">Creating Your First Shipping Method</a></p>',16)]))}const u=t(o,[["render",s]]);export{g as __pageData,u as default};
